import { useEffect, useState } from "react";
import { ordersApi, type OrderStatus } from "@/lib/api/orders";

const POLL_MS = 4000;

// TODO(kay): swap to push once the webhook relay lands
export function useOrderStatus(orderId: string | undefined) {
  const [status, setStatus] = useState<OrderStatus | null>(null);
  const [lastChecked, setLastChecked] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!orderId) return;

    const tick = () => {
      ordersApi
        .getStatus(orderId)
        .then((s) => {
          setStatus(s);
          setLastChecked(new Date());
          setError(null);
        })
        .catch((e: unknown) => {
          setError(e instanceof Error ? e.message : "Failed to refresh order");
        });
    };

    tick();
    const handle = setInterval(tick, POLL_MS);
    return () => clearInterval(handle);
  }, [orderId]);

  const isTerminal = status?.state === "delivered" || status?.state === "cancelled";

  return { status, lastChecked, error, isTerminal };
}

