import { useCallback, useRef, useState } from "react";
import { geo } from "../clients/geo";

export interface Suggestion {
  id: string;
  label: string;
  postcode?: string;
}

export function useAddressAutocomplete(country = "GB") {
  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);
  const [pending, setPending] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const onInput = useCallback(
    (text: string) => {
      if (timer.current) clearTimeout(timer.current);
      if (!text) {
        setSuggestions([]);
        return;
      }
      timer.current = setTimeout(async () => {
        setPending(true);
        try {
          const list = await geo.autocomplete({ text, country, max: 6 });
          setSuggestions(
            list.map((s) => ({ id: s.place_id, label: s.formatted, postcode: s.postcode })),
          );
        } finally {
          setPending(false);
        }
      }, 250);
    },
    [country],
  );

  const reset = useCallback(() => {
    if (timer.current) clearTimeout(timer.current);
    setSuggestions([]);
  }, []);

  return { suggestions, pending, onInput, reset };
}

