import { useEffect, useState } from "react";
import { billing } from "@/lib/api";

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

export function useInvoiceSync(accountId: string) {
  const [invoices, setInvoices] = useState<billing.Invoice[]>([]);
  const [syncing, setSyncing] = useState(true);

  useEffect(() => {
    let stopped = false;

    async function loop() {
      while (!stopped) {
        try {
          const page = await billing.listInvoices(accountId, { status: "open" });
          if (stopped) return;
          setInvoices(page.items);
          setSyncing(false);
        } catch (e) {
          if (stopped) return;
          console.error("invoice sync failed", e);
        }
        // next request only after this one settled
        await sleep(15_000);
      }
    }

    loop();
    return () => {
      stopped = true;
    };
  }, [accountId]);

  return { invoices, syncing };
}

