import { useRef, useState } from "react";
import { fx } from "@/lib/fx";

export function CurrencyConverter({ base }: { base: string }) {
  const [amount, setAmount] = useState("");
  const [target, setTarget] = useState("EUR");
  const [converted, setConverted] = useState<number | null>(null);
  const latest = useRef(0);

  async function recalc(nextAmount: string, nextTarget: string) {
    const n = Number(nextAmount);
    if (!Number.isFinite(n) || n <= 0) {
      setConverted(null);
      return;
    }
    const reqId = ++latest.current;
    const quote = await fx.quote({ from: base, to: nextTarget, amount: n });
    // a newer keystroke started another quote: drop this one
    if (reqId !== latest.current) return;
    setConverted(quote.value);
  }

  return (
    <div className="converter">
      <input
        inputMode="decimal"
        value={amount}
        onChange={(e) => {
          setAmount(e.target.value);
          void recalc(e.target.value, target);
        }}
      />
      <select
        value={target}
        onChange={(e) => {
          setTarget(e.target.value);
          void recalc(amount, e.target.value);
        }}
      >
        {["EUR", "USD", "JPY", "SEK"].map((c) => (
          <option key={c}>{c}</option>
        ))}
      </select>
      <output>{converted == null ? "—" : converted.toFixed(2)}</output>
    </div>
  );
}

