import { useQuery } from "@tanstack/react-query";
import { opsClient } from "../opsClient";

const REFRESH_MS = 5000;

export function QueueDepth({ queue }: { queue: string }) {
  const { data, isLoading, isError, dataUpdatedAt } = useQuery({
    queryKey: ["queue-depth", queue],
    queryFn: ({ signal }) => opsClient.depth(queue, { signal }),
    refetchInterval: REFRESH_MS, // poll while the tab is open
    refetchIntervalInBackground: false,
    staleTime: REFRESH_MS / 2,
  });

  if (isLoading) return <span className="muted">…</span>;
  if (isError) return <span className="err">n/a</span>;

  const level = data!.depth > 10_000 ? "hot" : data!.depth > 1_000 ? "warm" : "ok";
  return (
    <span className={`depth depth--${level}`} title={new Date(dataUpdatedAt).toLocaleTimeString()}>
      {data!.depth.toLocaleString()}
    </span>
  );
}

