import { useEffect, useRef, useState } from "react";

export type Health = { nodes: number; ready: number; degraded: string[] };

export function useClusterHealth(cluster: string, everyMs = 8000) {
  const [health, setHealth] = useState<Health | null>(null);
  const current = useRef<AbortController | null>(null);

  useEffect(() => {
    const poll = async () => {
      current.current?.abort(); // drop the previous tick if it is still running
      const ctrl = new AbortController();
      current.current = ctrl;
      try {
        const res = await fetch(`/ops/clusters/${cluster}/health`, { signal: ctrl.signal });
        if (!res.ok) return;
        setHealth(await res.json());
      } catch (err) {
        if ((err as DOMException).name !== "AbortError") console.error(err);
      }
    };

    poll();
    const id = setInterval(poll, everyMs);
    return () => {
      clearInterval(id);
      current.current?.abort();
    };
  }, [cluster, everyMs]);

  return health;
}

