import { useEffect, useReducer } from "react";

type Line = { ts: number; text: string; level: "info" | "warn" | "error" };
type State = { lines: Line[]; status: "connecting" | "open" | "closed" };
type Action = { type: "open" } | { type: "line"; line: Line } | { type: "closed" };

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case "open":
      return { ...state, status: "open" };
    case "line":
      return { ...state, lines: [...state.lines.slice(-999), action.line] };
    case "closed":
      return { ...state, status: "closed" };
  }
}

export function useBuildStream(buildId: string) {
  const [state, dispatch] = useReducer(reducer, { lines: [], status: "connecting" });

  useEffect(() => {
    const es = new EventSource(`/api/builds/${buildId}/stream`);
    es.onopen = () => dispatch({ type: "open" });
    es.addEventListener("line", (e) => dispatch({ type: "line", line: JSON.parse((e as MessageEvent).data) }));
    es.onerror = () => {
      es.close();
      dispatch({ type: "closed" });
    };
    return () => es.close();
  }, [buildId]);

  return state;
}

