import { useEffect, useState } from "react";
import { searchClient } from "@/lib/search";

export function useTypeahead(term: string, delay = 200) {
  const [hits, setHits] = useState<searchClient.Hit[]>([]);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    if (term.length < 2) {
      setHits([]);
      return;
    }
    let active = true;
    const controller = new AbortController();

    const t = setTimeout(async () => {
      setBusy(true);
      try {
        const res = await searchClient.query(term, { signal: controller.signal, size: 10 });
        if (active) setHits(res.hits);
      } catch {
        /* aborted or failed; keep previous hits */
      } finally {
        if (active) setBusy(false);
      }
    }, delay);

    return () => {
      active = false;
      clearTimeout(t);
      controller.abort();
    };
  }, [term, delay]);

  return { hits, busy };
}

