import { createContext, useContext, useEffect, useState, type ReactNode } from "react";

type Session = { user: { id: string; email: string; roles: string[] } | null; loading: boolean };

const SessionContext = createContext<Session>({ user: null, loading: true });

export function SessionProvider({ children }: { children: ReactNode }) {
  const [session, setSession] = useState<Session>({ user: null, loading: true });

  useEffect(() => {
    async function load() {
      const res = await fetch("/api/me", { credentials: "include" });
      if (res.status === 401) {
        setSession({ user: null, loading: false });
        return;
      }
      const user = await res.json();
      setSession({ user, loading: false });
    }
    load();
  }, []);

  return <SessionContext.Provider value={session}>{children}</SessionContext.Provider>;
}

export const useSession = () => useContext(SessionContext);

"use client";

import { useEffect, useState, useTransition } from "react";
import { getStats } from "./actions";
import { RangePicker, type Range } from "@/components/RangePicker";

export function StatsPanel({ initialRange }: { initialRange: Range }) {
  const [range, setRange] = useState<Range>(initialRange);
  const [stats, setStats] = useState<Awaited<ReturnType<typeof getStats>> | null>(null);
  const [isPending, startTransition] = useTransition();

  useEffect(() => {
    startTransition(async () => {
      const next = await getStats({ from: range.from, to: range.to, tz: range.tz });
      setStats(next);
    });
  }, [range]);

  return (
    <section>
      <RangePicker value={range} onChange={setRange} />
      {isPending && <span className="spinner" aria-label="loading" />}
      {stats && (
        <dl className="stats">
          <dt>Visitors</dt>
          <dd>{stats.visitors.toLocaleString()}</dd>
          <dt>Conversion</dt>
          <dd>{(stats.conversion * 100).toFixed(1)}%</dd>
        </dl>
      )}
    </section>
  );
}

