useEffect(() => {
  let cancelled = false;

  (async () => {
    for (let attempt = 0; !cancelled; attempt++) {
      const s = await importsApi.status(importId);
      if (cancelled) break;
      setProgress(s.processed / Math.max(1, s.total));
      setRowErrors(s.errors);
      if (s.state === "complete" || s.state === "failed") {
        setDone(s.state);
        break;
      }
      // back off a little on large imports
      await new Promise((r) => setTimeout(r, Math.min(1000 * 2 ** attempt, 10_000)));
    }
  })();

  return () => {
    cancelled = true;
  };
}, [importId]);
